def build_context(documents: List[Dict]) -> str:
blocks = []
for i, doc in enumerate(documents):
blocks.append(f"""### Document {i+1}
**Title:** {doc.get('report_name', 'Untitled')}
**Source:** {doc.get('source_type', 'Unknown')}
**Published:** {doc.get('report_published', 'Unknown')}
**Threat Actors:** {', '.join(doc.get('threat_actors', []))}
**TTPs:** {', '.join(doc.get('ttps', []))}
**Content Preview:**
{doc.get('text', '')[:1500]}... """)
return "\n\n".join(blocks)
